INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('f19f7093-d270-46d1-9ce8-7a088991e5d3', '150f78d3-019b-40c0-962e-a83576309ea5', 5, 'A Fortaleza Mansa', NULL, '{"intro": "A mansid\u00e3o \u00e9 o dom\u00ednio total das pr\u00f3prias paix\u00f5es.", "prayer": "Pe\u00e7a um cora\u00e7\u00e3o manso e humilde.", "practice": "Responda com do\u00e7ura a uma provoca\u00e7\u00e3o hoje.", "reflection": "A verdadeira for\u00e7a n\u00e3o \u00e9 a que grita, \u00e9 a que sustenta.", "journal_prompt": "A sua for\u00e7a vem do medo ou da paz?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;